      if (error.code !== "ENOENT") throw new Error("The project package.json is invalid or unreadable");
      await fsp.writeFile(manifest, JSON.stringify({ name: "limix-skill-project", version: "1.0.0", private: true }, null, 2) + "\n", { flag: "wx" });
